// Gather all tickets from all projects
const mgmtTickets = $('Fetch MGMT Tickets').all().map(i => i.json);
const learnTickets = $('Fetch LEARN Tickets').all().map(i => i.json);
const gradeTickets = $('Fetch GRADE Tickets').all().map(i => i.json);
const pulseTickets = $('Fetch PULSE Tickets').all().map(i => i.json);
const infraTickets = $('Fetch INFRA Tickets').all().map(i => i.json);
const backTickets = $('Fetch BACK Tickets').all().map(i => i.json);
const linkedTickets = $('Fetch All Links').all().map(i => i.json);

// Combine all tickets
const allTickets = [...mgmtTickets, ...learnTickets, ...gradeTickets, ...pulseTickets, ...infraTickets, ...backTickets];

// Create a map of linked issues for quick lookup
const linkMap = {};
linkedTickets.forEach(t => {
  if (t.fields?.issuelinks) {
    linkMap[t.key] = t.fields.issuelinks.map(link => ({
      type: link.type?.name || 'Related',
      direction: link.inwardIssue ? 'inward' : 'outward',
      linkedKey: link.inwardIssue?.key || link.outwardIssue?.key,
      linkedStatus: link.inwardIssue?.fields?.status?.name || link.outwardIssue?.fields?.status?.name
    }));
  }
});

// Calculate days since creation and last update
const now = new Date();
const calcDays = (dateStr) => {
  if (!dateStr) return 0;
  const date = new Date(dateStr);
  return Math.floor((now - date) / (1000 * 60 * 60 * 24));
};

// Enrich each ticket
const enrichedTickets = allTickets.map(ticket => {
  const created = ticket.fields?.created;
  const updated = ticket.fields?.updated;
  const ageDays = calcDays(created);
  const staleDays = calcDays(updated);
  const links = linkMap[ticket.key] || [];

  // Check if blocked
  const blockers = links.filter(l => 
    l.type === 'Blocks' && l.direction === 'inward' && 
    l.linkedStatus !== 'Done' && l.linkedStatus !== 'Closed'
  );

  // Check if blocking others
  const blocking = links.filter(l => 
    l.type === 'Blocks' && l.direction === 'outward' && 
    l.linkedStatus !== 'Done' && l.linkedStatus !== 'Closed'
  );

  return {
    key: ticket.key,
    project: ticket.fields?.project?.key,
    summary: ticket.fields?.summary?.substring(0, 100),
    status: ticket.fields?.status?.name,
    priority: ticket.fields?.priority?.name || 'Medium',
    priorityId: ticket.fields?.priority?.id || '3',
    type: ticket.fields?.issuetype?.name,
    labels: ticket.fields?.labels || [],
    assignee: ticket.fields?.assignee?.displayName || 'Unassigned',
    reporter: ticket.fields?.reporter?.displayName || 'Unknown',
    created: created,
    updated: updated,
    ageDays: ageDays,
    staleDays: staleDays,
    isStale: staleDays >= 7,
    isVeryStale: staleDays >= 14,
    isBlocked: blockers.length > 0,
    blockedBy: blockers.map(b => b.linkedKey),
    isBlocking: blocking.length > 0,
    blockingCount: blocking.length,
    relatedTickets: links.map(l => l.linkedKey),
    storyPoints: ticket.fields?.customfield_10016 || ticket.fields?.customfield_storypoints || 1,
    sprint: ticket.fields?.sprint?.name || null,
    epicLink: ticket.fields?.customfield_10014 || null
  };
});

// Identify different categories
const staleTickets = enrichedTickets.filter(t => t.isStale && !t.isBlocked);
const blockedTickets = enrichedTickets.filter(t => t.isBlocked);
const highPriorityOld = enrichedTickets.filter(t => 
  (t.priority === 'Highest' || t.priority === 'High') && t.ageDays > 14
);
const unassigned = enrichedTickets.filter(t => t.assignee === 'Unassigned');
const criticalPath = enrichedTickets.filter(t => t.isBlocking && t.blockingCount >= 2);

// Calculate project stats
const projectStats = {};
['MGMT', 'LEARN', 'GRADE', 'PULSE', 'INFRA', 'BACK'].forEach(proj => {
  const projTickets = enrichedTickets.filter(t => t.project === proj);
  projectStats[proj] = {
    total: projTickets.length,
    stale: projTickets.filter(t => t.isStale).length,
    blocked: projTickets.filter(t => t.isBlocked).length,
    unassigned: projTickets.filter(t => t.assignee === 'Unassigned').length,
    avgAgeDays: projTickets.length > 0 ? 
      Math.round(projTickets.reduce((s, t) => s + t.ageDays, 0) / projTickets.length) : 0
  };
});

return {
  json: {
    timestamp: now.toISOString(),
    totalTickets: enrichedTickets.length,
    staleCount: staleTickets.length,
    blockedCount: blockedTickets.length,
    unassignedCount: unassigned.length,
    criticalPathCount: criticalPath.length,

    projectStats,

    // For AI analysis (limited to prevent token overflow)
    ticketsForAnalysis: enrichedTickets.slice(0, 50),
    staleTickets: staleTickets.slice(0, 20),
    blockedTickets: blockedTickets.slice(0, 15),
    highPriorityOld: highPriorityOld.slice(0, 10),
    criticalPath: criticalPath.slice(0, 10),
    unassigned: unassigned.slice(0, 15),

    // Full data for processing
    allEnrichedTickets: enrichedTickets
  }
};

