const aiResponse = $json;
const enrichedData = $('Enrich Ticket Data').first().json;

// Extract JSON from AI response
let recommendations = {};
try {
  const responseText = aiResponse.content?.[0]?.text || '';
  // Find JSON block in response
  const jsonMatch = responseText.match(/```json\n([\s\S]*?)\n```/);
  if (jsonMatch) {
    recommendations = JSON.parse(jsonMatch[1]);
  } else {
    // Try parsing the whole response as JSON
    const cleanText = responseText.replace(/```json\n?|```/g, '').trim();
    recommendations = JSON.parse(cleanText);
  }
} catch (e) {
  recommendations = {
    priorityChanges: [],
    staleActions: [],
    blockerActions: [],
    closureSuggestions: [],
    criticalPathPrioritization: [],
    summary: 'Failed to parse AI recommendations: ' + e.message,
    parseError: true
  };
}

// Validate and enrich recommendations with full ticket data
const ticketMap = {};
enrichedData.allEnrichedTickets.forEach(t => ticketMap[t.key] = t);

const validatedPriorityChanges = (recommendations.priorityChanges || []).filter(pc => 
  ticketMap[pc.key] && pc.suggestedPriority !== pc.currentPriority
).map(pc => ({
  ...pc,
  ticketData: ticketMap[pc.key]
}));

const validatedStaleActions = (recommendations.staleActions || []).filter(sa => 
  ticketMap[sa.key] && ticketMap[sa.key].isStale
).map(sa => ({
  ...sa,
  ticketData: ticketMap[sa.key]
}));

const validatedBlockerActions = (recommendations.blockerActions || []).filter(ba => 
  ticketMap[ba.blockedKey]
).map(ba => ({
  ...ba,
  ticketData: ticketMap[ba.blockedKey]
}));

return {
  json: {
    recommendations: {
      ...recommendations,
      priorityChanges: validatedPriorityChanges,
      staleActions: validatedStaleActions,
      blockerActions: validatedBlockerActions,
      closureSuggestions: recommendations.closureSuggestions || [],
      criticalPathPrioritization: recommendations.criticalPathPrioritization || []
    },
    enrichedData,
    actionCounts: {
      priorityChanges: validatedPriorityChanges.length,
      staleActions: validatedStaleActions.length,
      blockerActions: validatedBlockerActions.length,
      closureSuggestions: (recommendations.closureSuggestions || []).length,
      criticalPath: (recommendations.criticalPathPrioritization || []).length
    },
    timestamp: new Date().toISOString()
  }
};

const data = $('Parse AI Recommendations').first().json;
const priorityChanges = data.recommendations.priorityChanges || [];

return priorityChanges.map(pc => ({ json: pc }));

