const parsedData = $('Parse AI Recommendations').first()?.json;
const recommendations = parsedData?.recommendations || {};
const enrichedData = parsedData?.enrichedData || {};
const actionCounts = parsedData?.actionCounts || {};

// Build summary report
const report = {
  date: new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }),
  timestamp: new Date().toISOString(),

  backlogHealth: {
    totalTickets: enrichedData.totalTickets || 0,
    staleTickets: enrichedData.staleCount || 0,
    blockedTickets: enrichedData.blockedCount || 0,
    unassigned: enrichedData.unassignedCount || 0,
    criticalPath: enrichedData.criticalPathCount || 0
  },

  projectStats: enrichedData.projectStats || {},

  actionsTaken: {
    priorityChanges: actionCounts.priorityChanges || 0,
    staleComments: actionCounts.staleActions || 0,
    unblockTasksCreated: actionCounts.blockerActions || 0,
    closureSuggestions: actionCounts.closureSuggestions || 0
  },

  recommendations,

  aiSummary: recommendations.summary || 'No AI summary available'
};

return { json: report };

const report = $json;

// Determine health color
let healthColor = 3066993; // Green
const staleRatio = report.backlogHealth.staleTickets / Math.max(report.backlogHealth.totalTickets, 1);
const blockedRatio = report.backlogHealth.blockedTickets / Math.max(report.backlogHealth.totalTickets, 1);

if (staleRatio > 0.3 || blockedRatio > 0.2) {
  healthColor = 15158332; // Red
} else if (staleRatio > 0.15 || blockedRatio > 0.1) {
  healthColor = 16776960; // Yellow
}

// Build project stats string
const projectStatsStr = Object.entries(report.projectStats || {})
  .map(([proj, stats]) => `**${proj}**: ${stats.total} (${stats.stale} stale)`)
  .join(' | ');

// Build actions taken string
const actionsStr = [
  report.actionsTaken.priorityChanges > 0 ? `:arrow_up_down: ${report.actionsTaken.priorityChanges} priorities updated` : null,
  report.actionsTaken.staleComments > 0 ? `:hourglass: ${report.actionsTaken.staleComments} stale comments added` : null,
  report.actionsTaken.unblockTasksCreated > 0 ? `:unlock: ${report.actionsTaken.unblockTasksCreated} unblock tasks created` : null,
  report.actionsTaken.closureSuggestions > 0 ? `:wastebasket: ${report.actionsTaken.closureSuggestions} closure suggestions` : null
].filter(Boolean).join('\n') || 'No actions needed';

// Build closure suggestions if any
const closureSuggestions = (report.recommendations.closureSuggestions || []).slice(0, 5)
  .map(cs => `- [${cs.key}]: ${cs.reason}`)
  .join('\n');

// Build embed
const embed = {
  title: `:broom: Daily Backlog Grooming Report - ${report.date}`,
  description: report.aiSummary.substring(0, 2000),
  color: healthColor,
  fields: [
    {
      name: ':clipboard: Backlog Health',
      value: `Total: ${report.backlogHealth.totalTickets} | Stale: ${report.backlogHealth.staleTickets} | Blocked: ${report.backlogHealth.blockedTickets} | Unassigned: ${report.backlogHealth.unassigned}`,
      inline: false
    },
    {
      name: ':file_folder: By Project',
      value: projectStatsStr || 'No data',
      inline: false
    },
    {
      name: ':robot: Actions Taken',
      value: actionsStr,
      inline: false
    }
  ],
  footer: {
    text: 'SwjshAK Backlog Groomer | WF-BACK-01'
  },
  timestamp: new Date().toISOString()
};

// Add closure suggestions if any
if (closureSuggestions) {
  embed.fields.push({
    name: ':wastebasket: Suggested for Closure',
    value: closureSuggestions.substring(0, 1000),
    inline: false
  });
}

return {
  json: {
    embed,
    report,
    channelId: process.env.DISCORD_STANDUP_CHANNEL_ID || 'daily-standup'
  }
};

